<?php require '../includes/config.php';admin_only();$adminTitle='Blog';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($_POST['action']==='save'){$id=(int)($_POST['id']??0);$v=[trim($_POST['title']),trim($_POST['excerpt']),trim($_POST['body']),isset($_POST['published'])?1:0];if($id){$v[]=$id;$pdo->prepare('UPDATE posts SET title=?,excerpt=?,body=?,published=? WHERE id=?')->execute($v);}else{$pdo->prepare('INSERT INTO posts(title,excerpt,body,published) VALUES(?,?,?,?)')->execute($v);}}else{$pdo->prepare('DELETE FROM posts WHERE id=?')->execute([(int)$_POST['id']]);}header('Location:posts.php');exit;}$rows=$pdo->query('SELECT * FROM posts ORDER BY created_at DESC')->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM posts WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}include '_top.php';?><h1 class="title">Blog / News</h1><div class="row g-4"><div class="col-xl-5"><div class="table-card"><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']??''?>"><input required name="title" value="<?=e($edit['title']??'')?>" class="form-control mb-2" placeholder="Title"><textarea required name="excerpt" class="form-control mb-2" placeholder="Excerpt"><?=e($edit['excerpt']??'')?></textarea><textarea required name="body" rows="8" class="form-control mb-2" placeholder="Article body"><?=e($edit['body']??'')?></textarea><label><input type="checkbox" name="published" <?=!isset($edit['published'])||$edit['published']?'checked':''?>> Published</label><button class="btn btn-primary w-100 mt-3">Save Post</button></form></div></div><div class="col-xl-7"><?php foreach($rows as $r):?><div class="table-card mb-2"><b><?=e($r['title'])?></b><p><?=e($r['excerpt'])?></p><a href="?edit=<?=$r['id']?>">Edit</a> · <form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-link text-danger p-0">Delete</button></form></div><?php endforeach;?></div></div><?php include '_bottom.php';?>